solution.solution.cpp:
#include <cmath>
#include <string>
#include <utility>
#include <vector>

struct Rect { float x, y, w, h; };

struct DockNode
{
    std::string name;
    char split{ 0 };
    float ratio{ 0.5f };
    std::vector<DockNode> children;
};

static void place(const DockNode& node, const Rect& r, float splitter, std::vector<std::pair<std::string, Rect>>& out)
{
    if (node.split == 0 || node.children.size() != 2)
    {
        out.push_back({ node.name, r });
        return;
    }
    if (node.split == 'x')
    {
        const float share{ r.w - splitter };
        const float first{ std::floor(share * node.ratio) };
        place(node.children[0], { r.x, r.y, first, r.h }, splitter, out);
        place(node.children[1], { r.x + first + splitter, r.y, share - first, r.h }, splitter, out);
    }
    else
    {
        const float share{ r.h - splitter };
        const float first{ std::floor(share * node.ratio) };
        place(node.children[0], { r.x, r.y, r.w, first }, splitter, out);
        place(node.children[1], { r.x, r.y + first + splitter, r.w, share - first }, splitter, out);
    }
}

std::vector<std::pair<std::string, Rect>> layout(const DockNode& root, const Rect& area, float splitterSize)
{
    std::vector<std::pair<std::string, Rect>> out;
    place(root, area, splitterSize, out);
    return out;
}

unitTests:
DockNode leaf(const char* n) { DockNode d; d.name = n; return d; }
DockNode split(char axis, float ratio, DockNode a, DockNode b) { DockNode d; d.split = axis; d.ratio = ratio; d.children = { a, b }; return d; }
bool same(const Rect& r, float x, float y, float w, float h) { return r.x == x && r.y == y && r.w == w && r.h == h; }
TEST("the example") {
    const auto l = layout(split('x', 0.2f, leaf("Scene"), split('y', 0.75f, leaf("Viewport"), leaf("Log"))), { 0, 0, 1004, 704 }, 4);
    CHECK_EQ(l.size(), std::size_t{ 3 });
    CHECK_EQ(l[0].first, std::string("Scene")); CHECK(same(l[0].second, 0, 0, 200, 704));
    CHECK_EQ(l[1].first, std::string("Viewport")); CHECK(same(l[1].second, 204, 0, 800, 525));
    CHECK_EQ(l[2].first, std::string("Log")); CHECK(same(l[2].second, 204, 529, 800, 175));
}
TEST("a single leaf") { const auto l = layout(leaf("Only"), { 10, 20, 300, 200 }, 4); CHECK(same(l[0].second, 10, 20, 300, 200)); }
TEST("rounding goes to the second child") { const auto l = layout(split('x', 0.5f, leaf("a"), leaf("b")), { 0, 0, 105, 50 }, 4); CHECK(same(l[0].second, 0, 0, 50, 50)); CHECK(same(l[1].second, 54, 0, 51, 50)); }
TEST("offset area") { const auto l = layout(split('y', 0.5f, leaf("top"), leaf("bottom")), { 100, 50, 200, 104 }, 4); CHECK(same(l[0].second, 100, 50, 200, 50)); CHECK(same(l[1].second, 100, 104, 200, 50)); }

